-- Ticket: TCK-40 (R-50)
-- Chạy ngoài transaction cho bước CONCURRENTLY (yêu cầu autocommit của PostgreSQL).
-- Idempotent: dùng IF NOT EXISTS / IF EXISTS ở mọi bước.

-- ===== FORWARD =====

-- Bước 1: thêm cột NULL-able + DEFAULT (metadata-only, không quét bảng, PG >= 11)
SET lock_timeout = '1s';
SET statement_timeout = '5s';
ALTER TABLE orders
  ADD COLUMN IF NOT EXISTS status varchar(20) DEFAULT 'pending';

-- Bước 2: thêm CHECK constraint dạng NOT VALID trước (không quét, không khoá dài),
-- rồi VALIDATE riêng (chỉ lấy SHARE UPDATE EXCLUSIVE, không chặn đọc/ghi thường)
ALTER TABLE orders
  ADD CONSTRAINT IF NOT EXISTS chk_orders_status
  CHECK (status IN ('pending','confirmed','shipped','delivered','cancelled'))
  NOT VALID;
ALTER TABLE orders VALIDATE CONSTRAINT chk_orders_status;

-- Bước 3: backfill theo lô 5000 dòng, nghỉ 100ms giữa các lô (chỉ cần cho dòng
-- được tạo trước khi có DEFAULT; DEFAULT đã phủ dòng ghi mới trong lúc backfill)
-- Chạy bằng script ứng dụng/psql \watch, ví dụ:
-- DO $$
-- DECLARE affected int;
-- BEGIN
--   LOOP
--     UPDATE orders SET status = 'pending'
--     WHERE id IN (
--       SELECT id FROM orders WHERE status IS NULL LIMIT 5000
--     );
--     GET DIAGNOSTICS affected = ROW_COUNT;
--     EXIT WHEN affected = 0;
--     PERFORM pg_sleep(0.1);
--   END LOOP;
-- END $$;

-- Bước 4: tạo index CONCURRENTLY (không giữ khoá ghi/đọc bảng, chạy autocommit)
CREATE INDEX CONCURRENTLY IF NOT EXISTS idx_orders_user_id_status
  ON orders (user_id, status);

-- Pha 2 (KHÔNG chạy trong migration này — để migration riêng sau khi xác nhận
-- backfill 100% trên production): ALTER TABLE orders ALTER COLUMN status SET NOT NULL;

-- ===== ROLLBACK =====
-- DROP INDEX CONCURRENTLY IF EXISTS idx_orders_user_id_status;
-- ALTER TABLE orders DROP CONSTRAINT IF EXISTS chk_orders_status;
-- ALTER TABLE orders DROP COLUMN IF EXISTS status;
